function D.ContainsNormalized(word)
    if not word or word == "" then return false end
    if #word <= 3 then return D.short[word] == true end
    local key = string.sub(word, 1, 3)
    if not string.match(key, "^[a-z][a-z][a-z]$") then
        return D.special[word] == true
    end
    local blob = D.buckets[key]
    if not blob then return false end
    local suffix = string.sub(word, 4)
    return string.find(blob, "\n" .. suffix .. "\n", 1, true) ~= nil
end

return D
